//! Task 2.2 gate, daemon side: tokens issued by the cloud's `signing.py` verify
//! here with the pinned key; other keys and the wrong `aud` are rejected.
//!
//! The fixture (`packages/schemas/fixtures/signing/cloud_tokens.json`) is
//! generated by `services/cloud-api/tests/signing_fixture.py` with a test-only
//! key and the real issuing functions; the Python suite fails if it drifts.

use edge_daemon::{
    auth::{
        cloud_keys::KeyRing,
        jws::JwsError,
        lease::{
            effective_lease, verify_immo_lease, verify_lease, verify_pairing, Lease, TokenError,
        },
    },
    protocol::messages::{Feature, LeaseTier},
};
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../packages/schemas/fixtures/signing/cloud_tokens.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture exists"))
        .expect("fixture is JSON")
}

fn s<'a>(v: &'a Value, path: &[&str]) -> &'a str {
    path.iter()
        .fold(v, |v, k| &v[*k])
        .as_str()
        .unwrap_or_else(|| panic!("fixture field {path:?}"))
}

/// The fixture key pinned by `kid`, as `scripts/export_cloud_keys.py` pins a
/// production key (32 raw bytes from its hex form).
fn pinned(f: &Value) -> KeyRing {
    let hex = s(f, &["public_key_hex"]);
    assert_eq!(hex.len(), 64, "32-byte key");
    let raw: [u8; 32] = (0..32)
        .map(|i| u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).expect("hex"))
        .collect::<Vec<_>>()
        .try_into()
        .unwrap();
    KeyRing::from_raw([(s(f, &["kid"]).to_owned(), raw)]).expect("valid Ed25519 key")
}

fn now(f: &Value) -> u64 {
    f["now"].as_u64().unwrap()
}

#[test]
fn cloud_lease_verifies_with_pinned_key() {
    let f = fixture();
    let lease = verify_lease(s(&f, &["valid", "lease"]), &pinned(&f), now(&f)).expect("verifies");
    let want = &f["expected"]["lease"];
    assert_eq!(lease.tenant_id.as_deref(), Some(s(want, &["tenant_id"])));
    assert_eq!(lease.user_id.as_deref(), Some(s(want, &["user_id"])));
    assert_eq!(lease.tier, LeaseTier::Workshop);
    assert_eq!(
        lease.features,
        vec![Feature::UdsActive, Feature::CanRePro, Feature::J2534]
    );
    assert!(lease.aasra_verified && !lease.immo);
    assert_eq!(lease.rcid.as_deref(), Some(s(want, &["rcid"])));
    assert_eq!(lease.lease_ver, want["lease_ver"].as_i64().unwrap());
    assert_eq!(lease.expires_at, want["exp"].as_u64());
}

#[test]
fn cloud_pairing_verifies_for_its_origin_only() {
    let f = fixture();
    let (keys, token, origin) = (pinned(&f), s(&f, &["valid", "pairing"]), s(&f, &["origin"]));
    let pairing = verify_pairing(token, &keys, Some(origin), now(&f)).expect("verifies");
    assert_eq!(pairing.user_id, s(&f, &["expected", "pairing", "user_id"]));
    assert_eq!(
        pairing.tenant_id,
        s(&f, &["expected", "pairing", "tenant_id"])
    );
    assert_eq!(
        verify_pairing(token, &keys, Some("https://evil.example"), now(&f)),
        Err(TokenError::OriginMismatch)
    );
    assert_eq!(
        verify_pairing(token, &keys, None, now(&f)),
        Err(TokenError::OriginMismatch)
    );
}

#[test]
fn cloud_immo_lease_verifies_and_is_never_a_diagnostic_lease() {
    let f = fixture();
    let keys = pinned(&f);
    let immo =
        verify_immo_lease(s(&f, &["valid", "immo_lease"]), &keys, now(&f)).expect("verifies");
    let want = &f["expected"]["immo_lease"];
    assert_eq!(immo.session_id, s(want, &["session_id"]));
    assert_eq!(immo.jti, s(want, &["jti"]));
    assert_eq!(immo.oem, s(want, &["oem"]));
    let as_diag = s(&f, &["rejected", "immo_as_diagnostic_lease"]);
    assert_eq!(
        effective_lease(Some(as_diag), &keys, now(&f)),
        Lease::community()
    );
    assert_eq!(
        verify_immo_lease(s(&f, &["rejected", "lease_as_immo"]), &keys, now(&f)),
        Err(TokenError::Claim("lease_kind"))
    );
}

#[test]
fn other_keys_and_wrong_audience_rejected() {
    let f = fixture();
    let (keys, t) = (pinned(&f), now(&f));
    let bad = |name: &str| s(&f, &["rejected", name]).to_owned();

    assert_eq!(
        verify_lease(&bad("lease_signed_by_other_key"), &keys, t),
        Err(TokenError::Signature(JwsError::BadSignature))
    );
    assert!(matches!(
        verify_lease(&bad("lease_unknown_kid"), &keys, t),
        Err(TokenError::Signature(JwsError::UnknownKey(_)))
    ));
    assert_eq!(
        verify_lease(&bad("lease_expired"), &keys, t),
        Err(TokenError::Expired)
    );
    for name in ["pairing_as_lease", "session_as_lease"] {
        assert!(
            matches!(
                verify_lease(&bad(name), &keys, t),
                Err(TokenError::WrongAudience(_))
            ),
            "{name}"
        );
    }
    assert!(matches!(
        verify_pairing(&bad("lease_as_pairing"), &keys, Some(s(&f, &["origin"])), t),
        Err(TokenError::WrongAudience(_))
    ));
    // With no pinned keys (the repository default) nothing verifies.
    assert!(matches!(
        verify_lease(s(&f, &["valid", "lease"]), &KeyRing::default(), t),
        Err(TokenError::Signature(JwsError::UnknownKey(_)))
    ));
}
